import type { ToolEvalTrace, ToolEvalAttempt } from "@/assistant/harness/evals/traceRecorder";

/**
 * Independent SCRIPTED regression corpus. These are hardcoded candidate tool
 * traces, NOT generated by reading scenario.expected and NOT Gemini measurements.
 * Correct, incorrect, incomplete and unnecessary paths are intentional.
 */
type ScriptedAttempt = [string, ToolEvalAttempt["status"], ToolEvalAttempt["failureKind"]?];

function trace(
  scenarioId: string,
  steps: readonly ScriptedAttempt[],
  observed: boolean | null,
  modality: "typed" | "voice",
  platform: "windows" | "android",
): ToolEvalTrace {
  return {
    version: 1, scenarioId, origin: "mock", modality, platform,
    attempts: steps.map(([tool, status, failureKind], index) => ({
      tool, status, failureKind: failureKind ?? null,
      startMs: 40 + index * 160, durationMs: 30 + index * 5,
    })),
    goal: observed === null
      ? { passed: null, source: "unverified" }
      : { passed: observed, source: "mock" },
  };
}

